def oracle():
    W,b,L,F=sp.symbols('W b L F',positive=True)
    muscle=sp.Matrix([b,0,0]).cross(sp.Matrix([0,F,0]))[2]
    load=sp.Matrix([L,0,0]).cross(sp.Matrix([0,-W,0]))[2]
    law=sp.solve(sp.Eq(muscle+load,0),F)[0]
    inverse_W=sp.solve(sp.Eq(F,law),W)[0]
    inverse_b=sp.solve(sp.Eq(F,law),b)[0]
    # Upward muscle and downward load; hinge reaction has no moment at O.
    reaction=sp.solve(sp.Eq(sp.Symbol('H')+F-W,0),sp.Symbol('H'))[0]
    if reaction.subs({F:60,W:10})!=-50:raise ValueError('Vertical hinge reaction sign failed')
    k,l=sp.symbols('k l',positive=True)
    ratio=sp.cancel(law.subs({W:k*W,b:l*b})/law)
    for opts,want,index in [([W*b/L,W*L/b,W,2*W*L/b,W*L/(2*b)],law,1),([F*b/L,F*L/b,F/(L*b),2*F*b/L,F*b/(2*L)],inverse_W,0),([k/l,k*l,l/k,k**2/l,k+l],ratio,0)]:
        if [i for i,v in enumerate(opts) if sp.cancel(v-want)==0]!=[index]:raise ValueError('Biceps symbolic choices not unique as general laws')
    length=sp.Rational(3,10);short=sp.Rational(1,20);long=sp.Rational(1,10)
    def force(weight,arm):return law.subs({L:length,W:weight,b:arm})
    A,B=force(10,short),force(30,long)
    c,o=sp.symbols('c o',real=True)
    cal=sp.solve([sp.Eq(c*A+o,121),sp.Eq(c*B+o,181)],(c,o))
    C=(241-cal[o])/cal[c]
    # Rank loss: W=200N/m*b makes measured F identically 60N.
    constrained=sp.cancel(law.subs({W:200*b,L:length}))
    if constrained!=60 or sp.diff(constrained,b)!=0:raise ValueError('Biceps nonidentifiability proof failed')
    if [force(200*t,t) for t in [short,long,sp.Rational(1,5)]]!=[60,60,60]:raise ValueError('Three distinct admissible pairs diagnostic failed')
    if (A+B)/2-force(20,sp.Rational(3,40))!=-5:raise ValueError('Mean outputs vs input means diagnostic failed')
    U=SI.Quantity
    cm=(U(30,'cm')/U(5,'cm')).to('')
    arm=(U(10,'N')*U(Fraction(3,10),'m')/U(60,'N')).to('m')
    weight=(U(120,'N')*U(Fraction(1,20),'m')/U(Fraction(3,10),'m')).to('N')
    constrained_si=(U(200,'N/m')*U(Fraction(3,10),'m')).to('N')
    if (cm.magnitude,arm.magnitude,weight.magnitude,constrained_si.magnitude)!=(6,Fraction(1,20),20,60):raise ValueError('Pint exact biceps dimensions/conversions failed')
    return [A,'N','F=WL/b','Da 60 a 120 N',inverse_W.subs({F:60,b:short,L:length}),inverse_b.subs({W:10,L:length,F:60}),force(10,long)/A,120-A,'W=Fb/L','κ₁ / κ₂',B/A,(A+B)/2,inverse_b.subs({W:30,L:length,F:sp.Rational(3,2)*A})/short,inverse_W.subs({F:270/(sp.Integer(180)/A),b:long,L:length}),inverse_W.subs({F:C,b:short,L:length}),'Infinite']

